<div class="card form-card"><form method="post" action="<?= $link($editing?'/users/'.$editing['id'].'/save':'/users/save') ?>"><?= $csrf ?><div class="form-grid"><label>Name<input name="name" value="<?= $e($editing['name']??'') ?>" required></label><label>Username<input name="username" value="<?= $e($editing['username']??'') ?>" required></label></div><label><?= $editing?'New password (leave blank to retain password)':'Password' ?><input type="password" name="password" minlength="12" maxlength="72" <?= $editing?'':'required' ?> autocomplete="new-password"></label><div class="form-grid"><label>Role<select name="role"><?php foreach(['administrator','technician','read-only'] as $role): ?><option value="<?= $e($role) ?>" <?= ($editing['role']??'read-only')===$role?'selected':'' ?>><?= $e(ucfirst($role)) ?></option><?php endforeach; ?></select></label><label>Audience<select name="audience"><option value="staff" <?= ($editing['audience']??'staff')==='staff'?'selected':'' ?>>Staff</option><option value="client" <?= ($editing['audience']??'')==='client'?'selected':'' ?>>Client (read-only)</option></select></label></div><p class="help">Client users see only client-visible documentation. Staff read-only users can also see internal documentation.</p><label class="checkbox"><input type="checkbox" name="active" value="1" <?= !$editing||$editing['active']?'checked':'' ?>>Active account</label><label class="checkbox"><input type="checkbox" name="require_mfa" value="1" <?= !empty($editing['require_mfa'])?'checked':'' ?>>Require authenticator MFA</label><h2>Organization assignments</h2><p class="help">Administrators access all organizations. Other roles access only selected organizations.</p><?php foreach($organizations as $o): ?><label class="checkbox"><input type="checkbox" name="organizations[]" value="<?= $e($o['id']) ?>" <?= in_array($o['id'],$editing['organizations']??[],false)?'checked':'' ?>><?= $e($o['name']) ?></label><?php endforeach; ?><div class="form-actions"><button class="button">Save user</button><a class="button secondary" href="<?= $link('/users') ?>">Cancel</a></div></form></div>
